combatFormula:
(function () {
    // Initialize battle log
    let log = [];

    // Stimulant consumption multiplier by class (global for use throughout combat)
    const stimConsumptionMultiplier = {
        1: 1.0,   // XXS - 1 crew needs 1 stim
        2: 0.9,   // XS - Slightly more efficient
        3: 0.8,   // S
        4: 0.7,   // M
        5: 0.6,   // L - Bulk efficiency
        6: 0.5,   // XL
        7: 0.4,   // XXL
        9: 0.3    // TTN - Most efficient per crew
    };

    // RNG helper function
    function randomRange(min, max) {
        return Math.random() * (max - min) + min;
    }

    // Roll for percentage chance (returns true/false)
    function rollChance(chance) {
        return Math.random() < chance;
    }

    // Get ship size from stats
    function getShipSize(fleet) {
        return fleet.ship_size || 100; // Default to 100 if not specified
    }

    // Calculate hit chance based on ship sizes (using actual size values)
    function calculateSizeBasedHitChance(attackerSize, defenderSize) {
        const baseHitChance = 0.85; // 85% base

        // Calculate size ratio
        const sizeRatio = attackerSize / defenderSize;

        // Size penalty/bonus calculation
        // If attacker is larger (ratio > 1), apply penalty
        // If attacker is smaller (ratio < 1), apply bonus
        let sizeModifier = 1;

        if (sizeRatio > 1) {
            // Larger attacker has harder time hitting smaller target
            // Every 2x size = -15% hit chance
            const scaleFactor = Math.log2(sizeRatio);
            sizeModifier = 1 - (scaleFactor * 0.15);
        } else if (sizeRatio < 1) {
            // Smaller attacker has easier time hitting larger target
            // Every 0.5x size = +5% hit chance
            const scaleFactor = Math.log2(1 / sizeRatio);
            sizeModifier = 1 + (scaleFactor * 0.05);
        }

        const hitChance = baseHitChance * sizeModifier;
        return Math.max(0.05, Math.min(1.0, hitChance)); // Clamp between 5% and 100%
    }

    // Combat configuration
    const config = {
        // Cooldown settings
        defaultAttackCooldown: 2,    // rounds
        cooldownTickPerRound: 1,

        // Alpha bonuses (by level 0-4)
        alphaStrikeBonuses: [0, 10, 20, 30, 40], // Percent damage bonus
        alphaShieldReductions: [0, 0.1, 0.2, 0.3, 0.4], // Damage reduction

        // Ammo
        ammoPerAttack: 1,

        // Combat limits
        maxRounds: 1000,
        minDamageFloor: 0.1
    };

    // Get parameters from window
    let firstStriker = window.combatFirstStriker || 'left';

    // Get alpha tier levels (0-4)
    let leftAlphaStrikeLevel = window.leftAlphaStrikeLevel || 0;
    let rightAlphaStrikeLevel = window.rightAlphaStrikeLevel || 0;
    let leftAlphaShieldLevel = window.leftAlphaShieldLevel || 0;
    let rightAlphaShieldLevel = window.rightAlphaShieldLevel || 0;

    // Get consumables from window (if available)
    let leftConsumables = window.leftConsumables || null;
    let rightConsumables = window.rightConsumables || null;

    // Calculate alpha bonuses from tier levels
    let leftAlphaStrikeBonus = config.alphaStrikeBonuses[leftAlphaStrikeLevel];
    let rightAlphaStrikeBonus = config.alphaStrikeBonuses[rightAlphaStrikeLevel];
    let leftAlphaShieldReduction = config.alphaShieldReductions[leftAlphaShieldLevel];
    let rightAlphaShieldReduction = config.alphaShieldReductions[rightAlphaShieldLevel];

    // Get skill levels (0-4)
    let leftFlightSpeedLevel = window.leftFlightSpeedLevel || 0;
    let rightFlightSpeedLevel = window.rightFlightSpeedLevel || 0;
    let leftManeuverabilityLevel = window.leftManeuverabilityLevel || 0;
    let rightManeuverabilityLevel = window.rightManeuverabilityLevel || 0;

    // Calculate skill bonuses
    let leftFlightSpeedBonus = 1 + (leftFlightSpeedLevel * 0.1);
    let rightFlightSpeedBonus = 1 + (rightFlightSpeedLevel * 0.1);
    let leftManeuverabilityBonus = leftManeuverabilityLevel * 0.05;
    let rightManeuverabilityBonus = rightManeuverabilityLevel * 0.05;

    log.push(`=== COMBAT CONFIGURATION ===`);
    log.push(`First striker: ${firstStriker}`);
    log.push(`Left: Alpha Strike Tier ${leftAlphaStrikeLevel} (+${leftAlphaStrikeBonus}%), Alpha Shield Tier ${leftAlphaShieldLevel} (-${(leftAlphaShieldReduction * 100).toFixed(0)}%)`);
    log.push(`Right: Alpha Strike Tier ${rightAlphaStrikeLevel} (+${rightAlphaStrikeBonus}%), Alpha Shield Tier ${rightAlphaShieldLevel} (-${(rightAlphaShieldReduction * 100).toFixed(0)}%)`);
    log.push(`Left skills: Flight Speed Lv${leftFlightSpeedLevel} (+${((leftFlightSpeedBonus - 1) * 100).toFixed(0)}%), Maneuverability Lv${leftManeuverabilityLevel} (+${(leftManeuverabilityBonus * 100).toFixed(0)}% dodge)`);
    log.push(`Right skills: Flight Speed Lv${rightFlightSpeedLevel} (+${((rightFlightSpeedBonus - 1) * 100).toFixed(0)}%), Maneuverability Lv${rightManeuverabilityLevel} (+${(rightManeuverabilityBonus * 100).toFixed(0)}% dodge)`);

    // Get ship classes for consumable calculations (before applying consumables)
    let leftClass = left.Class || left.class || 3; // Default to Small if not specified
    let rightClass = right.Class || right.class || 3;
    log.push(`Ship classes: Left=Class ${leftClass}, Right=Class ${rightClass}`);

    // Apply consumable modifiers if present
    function applyConsumableModifiers(stats, consumables, crew, shipClass) {
        if (!consumables || !consumables.stimulants) return stats;

        const modifiedStats = { ...stats };

        // Use global stimConsumptionMultiplier (defined at top of file)

        consumables.stimulants.forEach(stimulant => {
            if (stimulant.data && stimulant.allocation > 0) {
                // Calculate stimulant potency based on allocation
                const classMultiplier = stimConsumptionMultiplier[shipClass] || 1.0;
                const effectiveUnits = stimulant.allocation * classMultiplier;

                // Potency scales logarithmically with units
                const potencyBonus = 1.0 + (0.1 * Math.log10(Math.max(1, effectiveUnits)));

                Object.keys(stimulant.data).forEach(statName => {
                    if (statName !== 'subGroups' && modifiedStats[statName] !== undefined) {
                        const statData = stimulant.data[statName];

                        if (statData.type === 'multiplicative' || statData.multiplicativeValue) {
                            const baseMultiplier = statData.multiplicativeValue || 1.0;
                            const scaledMultiplier = 1.0 + ((baseMultiplier - 1.0) * potencyBonus);
                            modifiedStats[statName] = modifiedStats[statName] * scaledMultiplier;
                        } else if (statData.type === 'additive' || statData.additiveValue) {
                            const baseAddition = statData.additiveValue || 0;
                            const scaledAddition = baseAddition * potencyBonus;
                            modifiedStats[statName] = modifiedStats[statName] + scaledAddition;
                        } else if (statData.baseValue !== undefined) {
                            const scaledValue = statData.baseValue * potencyBonus;
                            modifiedStats[statName] = modifiedStats[statName] + scaledValue;
                        }
                    }
                });
            }
        });

        return modifiedStats;
    }

    // Apply consumables to fleet stats
    if (leftConsumables) {
        log.push(`Left fleet has ${leftConsumables.stimulants ? leftConsumables.stimulants.length : 0} stimulants active`);
        left = applyConsumableModifiers(left, leftConsumables, left.required_crew || 1, leftClass);
    }
    if (rightConsumables) {
        log.push(`Right fleet has ${rightConsumables.stimulants ? rightConsumables.stimulants.length : 0} stimulants active`);
        right = applyConsumableModifiers(right, rightConsumables, right.required_crew || 1, rightClass);
    }

    // Get ship sizes
    let leftShipSize = getShipSize(left);
    let rightShipSize = getShipSize(right);
    log.push(`Ship sizes: Left=${leftShipSize}, Right=${rightShipSize} (ratio: ${(leftShipSize / rightShipSize).toFixed(2)})`);

    // Calculate base damage types
    let leftDamages = {
        base: left.damage || 0,
        kinetic: left.damage_kinetic || 0,
        energy: left.damage_energy || 0,
        emp: left.damage_emp || 0,
        superchill: left.damage_superchill || 0,
        graygoo: left.damage_graygoo || 0,
        shockwave: left.damage_shockwave || 0,
        heat: left.damage_heat || 0,
        bomb: left.damage_bomb || 0
    };

    let rightDamages = {
        base: right.damage || 0,
        kinetic: right.damage_kinetic || 0,
        energy: right.damage_energy || 0,
        emp: right.damage_emp || 0,
        superchill: right.damage_superchill || 0,
        graygoo: right.damage_graygoo || 0,
        shockwave: right.damage_shockwave || 0,
        heat: right.damage_heat || 0,
        bomb: right.damage_bomb || 0
    };

    // Apply missile power to bomb damage
    let leftMissilePower = left.missile_power || 1;
    let rightMissilePower = right.missile_power || 1;
    let leftMissileCapacity = left.missile_capacity || 0;
    let rightMissileCapacity = right.missile_capacity || 0;

    if (leftMissileCapacity > 0 && leftDamages.bomb > 0) {
        let missileBoost = Math.min(leftMissilePower, leftMissileCapacity / 100);
        leftDamages.bomb *= missileBoost;
        log.push(`Left missile boost: x${missileBoost.toFixed(2)} on bomb damage`);
    }

    if (rightMissileCapacity > 0 && rightDamages.bomb > 0) {
        let missileBoost = Math.min(rightMissilePower, rightMissileCapacity / 100);
        rightDamages.bomb *= missileBoost;
        log.push(`Right missile boost: x${missileBoost.toFixed(2)} on bomb damage`);
    }

    // Calculate damage diversity bonus
    let leftDamageTypes = Object.values(leftDamages).filter(d => d > 0).length;
    let rightDamageTypes = Object.values(rightDamages).filter(d => d > 0).length;
    let leftDiversityBonus = 1 + Math.max(0, leftDamageTypes - 1) * 0.05;
    let rightDiversityBonus = 1 + Math.max(0, rightDamageTypes - 1) * 0.05;

    log.push(`Damage diversity: Left=${leftDamageTypes} types (+${((leftDiversityBonus - 1) * 100).toFixed(0)}%), Right=${rightDamageTypes} types (+${((rightDiversityBonus - 1) * 100).toFixed(0)}%)`);

    // Map counters
    let leftCounters = {
        kinetic: left.counter_flare || 0,
        energy: left.counter_energy_capacitor || 0,
        emp: left.counter_faraday_shielding || 0,
        superchill: left.counter_warming_plates || 0,
        graygoo: left.counter_healing_nanobots || 0,
        shockwave: left.counter_negative_rem_plating || 0,
        heat: left.counter_fire_suppressor || 0,
        bomb: left.counter_mine || 0,
        base: left.counter_decoy || 0
    };

    let rightCounters = {
        kinetic: right.counter_flare || 0,
        energy: right.counter_energy_capacitor || 0,
        emp: right.counter_faraday_shielding || 0,
        superchill: right.counter_warming_plates || 0,
        graygoo: right.counter_healing_nanobots || 0,
        shockwave: right.counter_negative_rem_plating || 0,
        heat: right.counter_fire_suppressor || 0,
        bomb: right.counter_mine || 0,
        base: right.counter_decoy || 0
    };

    // Stealth and scanner setup
    let leftStealth = left.stealth_power || 0;
    let rightStealth = right.stealth_power || 0;
    let leftScanPower = left.scan_power || 0;
    let rightScanPower = right.scan_power || 0;

    // Check if scanners break stealth
    let leftStealthBroken = rightScanPower >= leftStealth;
    let rightStealthBroken = leftScanPower >= rightStealth;

    // Track if stealth has been revealed (for first-strike auto-dodge)
    let leftStealthRevealed = leftStealthBroken;
    let rightStealthRevealed = rightStealthBroken;

    // Calculate dodge chance
    let leftSpeed = Math.max(left.subwarp_speed || 0, left.warp_speed || 0) * leftFlightSpeedBonus;
    let rightSpeed = Math.max(right.subwarp_speed || 0, right.warp_speed || 0) * rightFlightSpeedBonus;

    let leftBaseDodge = 0;
    let rightBaseDodge = 0;

    // Stealth dodge
    if (!leftStealthBroken && leftStealth > 0) {
        leftBaseDodge += Math.min(0.5, leftStealth / 100);
        log.push(`Left stealth active: ${(leftStealth / 100 * 100).toFixed(0)}% dodge chance`);
    } else if (leftStealth > 0) {
        log.push(`Left stealth broken by scanners`);
    }

    if (!rightStealthBroken && rightStealth > 0) {
        rightBaseDodge += Math.min(0.5, rightStealth / 100);
        log.push(`Right stealth active: ${(rightStealth / 100 * 100).toFixed(0)}% dodge chance`);
    } else if (rightStealth > 0) {
        log.push(`Right stealth broken by scanners`);
    }

    // Speed dodge
    leftBaseDodge += Math.min(0.2, Math.log10(1 + leftSpeed) / 20);
    rightBaseDodge += Math.min(0.2, Math.log10(1 + rightSpeed) / 20);

    // Maneuverability dodge
    leftBaseDodge += leftManeuverabilityBonus;
    rightBaseDodge += rightManeuverabilityBonus;

    // Note: Fuel modifiers will be applied after fuel is initialized
    // Dodge will be capped at 75% after fuel modifiers are applied

    // Initialize defenses
    let leftHP = left.hit_points || 0;
    let rightHP = right.hit_points || 0;
    let leftShields = left.shield_points || 0;
    let rightShields = right.shield_points || 0;

    log.push(`\n=== INITIAL STATS ===`);
    log.push(`Left: ${leftHP.toFixed(0)} HP, ${leftShields.toFixed(0)} shields`);
    log.push(`Right: ${rightHP.toFixed(0)} HP, ${rightShields.toFixed(0)} shields`);

    // Initialize combat state
    let leftCurrentHP = leftHP;
    let rightCurrentHP = rightHP;
    let leftCurrentShields = leftShields;
    let rightCurrentShields = rightShields;

    // Ammo tracking (use consumables if available, else ship capacity)
    let leftAmmo = leftConsumables && leftConsumables.standardResources && leftConsumables.standardResources.ammo !== undefined ?
        leftConsumables.standardResources.ammo : (left.ammo_capacity || Infinity);
    let rightAmmo = rightConsumables && rightConsumables.standardResources && rightConsumables.standardResources.ammo !== undefined ?
        rightConsumables.standardResources.ammo : (right.ammo_capacity || Infinity);

    // Track initial ammo for summary
    let leftInitialAmmo = leftAmmo;
    let rightInitialAmmo = rightAmmo;

    // Track other consumable resources
    let leftMissiles = leftConsumables && leftConsumables.standardResources ?
        leftConsumables.standardResources.missiles || 0 : 0;
    let rightMissiles = rightConsumables && rightConsumables.standardResources ?
        rightConsumables.standardResources.missiles || 0 : 0;

    let leftToolkits = leftConsumables && leftConsumables.standardResources ?
        leftConsumables.standardResources.toolkits || 0 : 0;
    let rightToolkits = rightConsumables && rightConsumables.standardResources ?
        rightConsumables.standardResources.toolkits || 0 : 0;

    // Track initial resources for summary
    let leftInitialMissiles = leftMissiles;
    let rightInitialMissiles = rightMissiles;
    let leftInitialToolkits = leftToolkits;
    let rightInitialToolkits = rightToolkits;

    // Extract consumable-related stats from fleets
    let leftRepairRate = left.repair_rate || 0;
    let rightRepairRate = right.repair_rate || 0;
    let leftRepairAbility = left.repair_ability || 1.0;  // Efficiency multiplier
    let rightRepairAbility = right.repair_ability || 1.0;
    let leftRepairEfficiency = left.repair_efficiency || 1.0; // Toolkits per repair
    let rightRepairEfficiency = right.repair_efficiency || 1.0;

    // Consumption rate modifiers (can be modified by components/skills)
    let leftAmmoConsumptionRate = left.ammo_consumption_rate || 1.0;
    let rightAmmoConsumptionRate = right.ammo_consumption_rate || 1.0;
    let leftMissileConsumptionRate = left.missile_consumption_rate || 1.0;
    let rightMissileConsumptionRate = right.missile_consumption_rate || 1.0;
    let leftCounterConsumptionRate = left.counter_consumption_rate || 1.0;
    let rightCounterConsumptionRate = right.counter_consumption_rate || 1.0;
    let leftFuelConsumptionRate = left.fuel_consumption_rate || 1.0;
    let rightFuelConsumptionRate = right.fuel_consumption_rate || 1.0;
    let leftFoodConsumptionRate = left.food_consumption_rate || 1.0;
    let rightFoodConsumptionRate = right.food_consumption_rate || 1.0;
    let leftToolkitConsumptionRate = left.toolkit_consumption_rate || 1.0;
    let rightToolkitConsumptionRate = right.toolkit_consumption_rate || 1.0;

    // Track other consumables
    let leftFood = leftConsumables && leftConsumables.standardResources ?
        leftConsumables.standardResources.food || 0 : 0;
    let rightFood = rightConsumables && rightConsumables.standardResources ?
        rightConsumables.standardResources.food || 0 : 0;
    let leftInitialFood = leftFood;
    let rightInitialFood = rightFood;

    let leftFuel = leftConsumables && leftConsumables.standardResources ?
        leftConsumables.standardResources.fuel || 0 : 0;
    let rightFuel = rightConsumables && rightConsumables.standardResources ?
        rightConsumables.standardResources.fuel || 0 : 0;
    let leftInitialFuel = leftFuel;
    let rightInitialFuel = rightFuel;

    // Calculate fuel modifiers (needed for dodge calculations)
    let leftFuelModifier = leftFuel > 0 ? 0.5 + (0.5 * (leftFuel / leftInitialFuel)) : 0.5;
    let rightFuelModifier = rightFuel > 0 ? 0.5 + (0.5 * (rightFuel / rightInitialFuel)) : 0.5;

    // Now apply fuel modifiers to dodge and cap it
    leftBaseDodge *= leftFuelModifier;
    rightBaseDodge *= rightFuelModifier;
    leftBaseDodge = Math.min(0.75, leftBaseDodge);
    rightBaseDodge = Math.min(0.75, rightBaseDodge);

    log.push(`Total dodge: Left=${(leftBaseDodge * 100).toFixed(0)}%, Right=${(rightBaseDodge * 100).toFixed(0)}%`);

    let leftCounterResource = leftConsumables && leftConsumables.standardResources ?
        leftConsumables.standardResources.counters || 0 : 0;
    let rightCounterResource = rightConsumables && rightConsumables.standardResources ?
        rightConsumables.standardResources.counters || 0 : 0;
    let leftInitialCounters = leftCounterResource;
    let rightInitialCounters = rightCounterResource;

    // Track depletion events
    let depletionEvents = [];

    // Calculate total fleet damage (sum of all damage types)
    let leftFleetDamage = Object.values(leftDamages).reduce((sum, dmg) => sum + dmg, 0);
    let rightFleetDamage = Object.values(rightDamages).reduce((sum, dmg) => sum + dmg, 0);

    // Class-based consumption rates
    const classConsumptionRates = {
        1: { ammo: 5, fuel: 2, food: 0.5, missile: 1, counter: 1 },   // XXS
        2: { ammo: 12, fuel: 5, food: 1.0, missile: 2, counter: 2 },   // XS
        3: { ammo: 35, fuel: 15, food: 3.0, missile: 3, counter: 3 },   // S
        4: { ammo: 100, fuel: 40, food: 8.0, missile: 5, counter: 5 },   // M
        5: { ammo: 300, fuel: 120, food: 25.0, missile: 8, counter: 8 }, // L
        6: { ammo: 900, fuel: 350, food: 75.0, missile: 12, counter: 12 }, // XL
        7: { ammo: 2500, fuel: 1000, food: 200.0, missile: 20, counter: 20 }, // XXL
        9: { ammo: 10000, fuel: 4000, food: 800.0, missile: 50, counter: 50 } // TTN
    };

    // Calculate ACTUAL ammo consumption rates
    let leftAmmoRate = Math.max(1, Math.floor(
        (classConsumptionRates[leftClass]?.ammo || 10) *
        leftAmmoConsumptionRate
    ));
    let rightAmmoRate = Math.max(1, Math.floor(
        (classConsumptionRates[rightClass]?.ammo || 10) *
        rightAmmoConsumptionRate
    ));

    // Consumables status moved to UI sidebar - no longer logged as text

    // Apply food modifiers
    let leftFoodModifier = leftFood > 0 ? 0.5 + (0.5 * (leftFood / leftInitialFood)) : 0.5;
    let rightFoodModifier = rightFood > 0 ? 0.5 + (0.5 * (rightFood / rightInitialFood)) : 0.5;

    // Apply food modifier to crew efficiency (affects repair rate, etc)
    if (left.repair_rate) left.repair_rate *= leftFoodModifier;
    if (right.repair_rate) right.repair_rate *= rightFoodModifier;

    log.push(`Food efficiency: Left=${(leftFoodModifier * 100).toFixed(0)}%, Right=${(rightFoodModifier * 100).toFixed(0)}%`);
    log.push(`Fuel efficiency: Left=${(leftFuelModifier * 100).toFixed(0)}%, Right=${(rightFuelModifier * 100).toFixed(0)}%`);

    // Track stimulant inventory and consumption
    let leftStimulantInventory = {};
    let rightStimulantInventory = {};
    let leftStimulantDurations = [];
    let rightStimulantDurations = [];

    // Per-round consumption rate: crew × class_efficiency × dosage_rate (0.5 = 50% crew dosage per round)
    const stimDosageRate = 0.5;

    // Initialize stimulant inventory from allocation
    if (leftConsumables && leftConsumables.stimulants) {
        leftConsumables.stimulants.forEach(stim => {
            if (stim.allocation > 0) {
                leftStimulantInventory[stim.name] = stim.allocation;

                // Special handling for Alpha Strike Serum - only for first striker, lasts 1 round
                if (stim.name === 'Alpha Strike Serum') {
                    if (config.firstStriker === 'left') {
                        const classMultiplier = stimConsumptionMultiplier[leftClass] || 1.0;
                        const consumeAmount = Math.ceil((left.required_crew || 1) * classMultiplier * stimDosageRate);

                        if (leftStimulantInventory[stim.name] >= consumeAmount) {
                            leftStimulantInventory[stim.name] -= consumeAmount;
                            leftStimulantDurations.push({
                                name: stim.name,
                                duration: 1, // Only 1 round - the alpha strike
                                effects: stim.data,
                                alphaStrikeOnly: true,
                                consumePerRound: consumeAmount
                            });
                            log.push(`Left fleet: Alpha Strike Serum active (1 round only - first strike, consumed ${consumeAmount} units)`);
                        }
                    } else {
                        log.push(`Left fleet: Alpha Strike Serum has no effect (not first striker)`);
                    }
                } else {
                    // Calculate consumption for initial application
                    const classMultiplier = stimConsumptionMultiplier[leftClass] || 1.0;
                    const consumePerRound = Math.ceil((left.required_crew || 1) * classMultiplier * stimDosageRate);
                    const baseDuration = stim.data.duration || 5;
                    const totalConsume = consumePerRound * baseDuration;

                    if (leftStimulantInventory[stim.name] >= totalConsume) {
                        leftStimulantInventory[stim.name] -= totalConsume;
                        leftStimulantDurations.push({
                            name: stim.name,
                            duration: baseDuration,
                            effects: stim.data,
                            consumePerRound: consumePerRound,
                            totalAllocated: stim.allocation
                        });
                        log.push(`Left fleet: ${stim.name} active (${baseDuration} rounds, ${consumePerRound} units/round)`);
                    }
                }
            }
        });
    }

    if (rightConsumables && rightConsumables.stimulants) {
        rightConsumables.stimulants.forEach(stim => {
            if (stim.allocation > 0) {
                rightStimulantInventory[stim.name] = stim.allocation;

                // Special handling for Alpha Strike Serum - only for first striker, lasts 1 round
                if (stim.name === 'Alpha Strike Serum') {
                    if (config.firstStriker === 'right') {
                        const classMultiplier = stimConsumptionMultiplier[rightClass] || 1.0;
                        const consumeAmount = Math.ceil((right.required_crew || 1) * classMultiplier * stimDosageRate);

                        if (rightStimulantInventory[stim.name] >= consumeAmount) {
                            rightStimulantInventory[stim.name] -= consumeAmount;
                            rightStimulantDurations.push({
                                name: stim.name,
                                duration: 1, // Only 1 round - the alpha strike
                                effects: stim.data,
                                alphaStrikeOnly: true,
                                consumePerRound: consumeAmount
                            });
                            log.push(`Right fleet: Alpha Strike Serum active (1 round only - first strike, consumed ${consumeAmount} units)`);
                        }
                    } else {
                        log.push(`Right fleet: Alpha Strike Serum has no effect (not first striker)`);
                    }
                } else {
                    // Calculate consumption for initial application
                    const classMultiplier = stimConsumptionMultiplier[rightClass] || 1.0;
                    const consumePerRound = Math.ceil((right.required_crew || 1) * classMultiplier * stimDosageRate);
                    const baseDuration = stim.data.duration || 5;
                    const totalConsume = consumePerRound * baseDuration;

                    if (rightStimulantInventory[stim.name] >= totalConsume) {
                        rightStimulantInventory[stim.name] -= totalConsume;
                        rightStimulantDurations.push({
                            name: stim.name,
                            duration: baseDuration,
                            effects: stim.data,
                            consumePerRound: consumePerRound,
                            totalAllocated: stim.allocation
                        });
                        log.push(`Right fleet: ${stim.name} active (${baseDuration} rounds, ${consumePerRound} units/round)`);
                    }
                }
            }
        });
    }

    // Cooldown tracking
    let leftCooldownTimer = 0;
    let rightCooldownTimer = 0;
    let leftAttackCooldown = config.defaultAttackCooldown;
    let rightAttackCooldown = config.defaultAttackCooldown;

    // Alpha effect tracking
    let leftAlphaStrikeUsed = false;
    let rightAlphaStrikeUsed = false;
    let leftAlphaShieldUsed = false;
    let rightAlphaShieldUsed = false;

    // Track first attack attempts (not just hits)
    let leftFirstAttackAttempted = false;
    let rightFirstAttackAttempted = false;

    // Aim ability for offsetting size penalties
    let leftAimAbility = left.aim_ability || 0;
    let rightAimAbility = right.aim_ability || 0;

    // Hit chance stat
    let leftHitChanceStat = left.hit_chance || 1;
    let rightHitChanceStat = right.hit_chance || 1;

    // Combat tracking
    let round = 0;
    let leftTotalDamageDealt = 0;
    let rightTotalDamageDealt = 0;
    let leftAttacks = 0;
    let rightAttacks = 0;
    let leftHits = 0;
    let rightHits = 0;

    log.push(`\n=== TURN-BASED COMBAT SIMULATION ===`);
    log.push(`Cooldowns: ${config.defaultAttackCooldown} rounds`);
    log.push(`Ammo per attack: Left=${leftAmmoRate}, Right=${rightAmmoRate} (class and damage based)`);

    // Main combat loop
    while (round < config.maxRounds && leftCurrentHP > 0 && rightCurrentHP > 0) {
        round++;
        log.push(`\n--- Round ${round} ---`);

        // STIMULANT DURATION TRACKING WITH AUTO RE-APPLICATION
        leftStimulantDurations = leftStimulantDurations.filter(stim => {
            stim.duration--;
            if (stim.duration <= 0) {
                log.push(`[STIMULANT] Left fleet's ${stim.name} has worn off`);

                // Check if we can re-apply (not for Alpha Strike)
                if (!stim.alphaStrikeOnly) {
                    const baseDuration = stim.effects.duration || 5;
                    const totalConsume = stim.consumePerRound * baseDuration;

                    if (leftStimulantInventory[stim.name] >= totalConsume) {
                        // Re-apply stimulant
                        leftStimulantInventory[stim.name] -= totalConsume;
                        stim.duration = baseDuration;
                        log.push(`[STIMULANT] Left fleet re-applied ${stim.name} (${baseDuration} more rounds, ${totalConsume} units consumed)`);
                        depletionEvents.push(`Round ${round}: Left ${stim.name} re-applied (${Math.floor(leftStimulantInventory[stim.name])} units remaining)`);
                        return true; // Keep in array
                    } else {
                        depletionEvents.push(`Round ${round}: Left ${stim.name} expired (insufficient units for re-application)`);
                        return false;
                    }
                } else {
                    depletionEvents.push(`Round ${round}: Left ${stim.name} expired`);
                    return false;
                }
            }
            return true;
        });

        rightStimulantDurations = rightStimulantDurations.filter(stim => {
            stim.duration--;
            if (stim.duration <= 0) {
                log.push(`[STIMULANT] Right fleet's ${stim.name} has worn off`);

                // Check if we can re-apply (not for Alpha Strike)
                if (!stim.alphaStrikeOnly) {
                    const baseDuration = stim.effects.duration || 5;
                    const totalConsume = stim.consumePerRound * baseDuration;

                    if (rightStimulantInventory[stim.name] >= totalConsume) {
                        // Re-apply stimulant
                        rightStimulantInventory[stim.name] -= totalConsume;
                        stim.duration = baseDuration;
                        log.push(`[STIMULANT] Right fleet re-applied ${stim.name} (${baseDuration} more rounds, ${totalConsume} units consumed)`);
                        depletionEvents.push(`Round ${round}: Right ${stim.name} re-applied (${Math.floor(rightStimulantInventory[stim.name])} units remaining)`);
                        return true; // Keep in array
                    } else {
                        depletionEvents.push(`Round ${round}: Right ${stim.name} expired (insufficient units for re-application)`);
                        return false;
                    }
                } else {
                    depletionEvents.push(`Round ${round}: Right ${stim.name} expired`);
                    return false;
                }
            }
            return true;
        });

        // Tick cooldowns
        if (leftCooldownTimer > 0) {
            leftCooldownTimer -= config.cooldownTickPerRound;
            log.push(`Left cooldown: ${leftCooldownTimer} rounds remaining`);
        }
        if (rightCooldownTimer > 0) {
            rightCooldownTimer -= config.cooldownTickPerRound;
            log.push(`Right cooldown: ${rightCooldownTimer} rounds remaining`);
        }

        // Determine who can attack this round
        let leftCanAttack = leftCooldownTimer <= 0 && leftAmmo >= leftAmmoRate;
        let rightCanAttack = rightCooldownTimer <= 0 && rightAmmo >= rightAmmoRate;

        if (!leftCanAttack && leftCooldownTimer <= 0 && leftAmmo < leftAmmoRate) {
            log.push(`Left fleet OUT OF AMMO - Cannot attack (needs ${leftAmmoRate}, has ${leftAmmo})`);
        }
        if (!rightCanAttack && rightCooldownTimer <= 0 && rightAmmo < rightAmmoRate) {
            log.push(`Right fleet OUT OF AMMO - Cannot attack (needs ${rightAmmoRate}, has ${rightAmmo})`);
        }

        // Build attack queue for simultaneous resolution
        let attacks = [];

        // Determine attack order based on first striker
        if (firstStriker === 'left') {
            if (leftCanAttack) attacks.push({ attacker: 'left', target: 'right' });
            if (rightCanAttack) attacks.push({ attacker: 'right', target: 'left' });
        } else {
            if (rightCanAttack) attacks.push({ attacker: 'right', target: 'left' });
            if (leftCanAttack) attacks.push({ attacker: 'left', target: 'right' });
        }

        // Process all attacks
        for (let attack of attacks) {
            let isLeftAttacking = attack.attacker === 'left';
            let damages = isLeftAttacking ? { ...leftDamages } : { ...rightDamages };
            let counters = isLeftAttacking ? rightCounters : leftCounters;
            let attackerSize = isLeftAttacking ? leftShipSize : rightShipSize;
            let defenderSize = isLeftAttacking ? rightShipSize : leftShipSize;
            let defenderDodge = isLeftAttacking ? rightBaseDodge : leftBaseDodge;
            let damageRange = isLeftAttacking ? (left.damage_range || 0) : (right.damage_range || 0);
            let aimAbility = isLeftAttacking ? leftAimAbility : rightAimAbility;
            let hitChanceStat = isLeftAttacking ? leftHitChanceStat : rightHitChanceStat;

            // Track attack attempt
            if (isLeftAttacking) {
                leftAttacks++;
                leftFirstAttackAttempted = true;
            } else {
                rightAttacks++;
                rightFirstAttackAttempted = true;
            }

            // Consume ammo and set cooldown BEFORE checking hit/miss
            if (isLeftAttacking) {
                leftAmmo -= leftAmmoRate;
                leftCooldownTimer = leftAttackCooldown;

                // Check for ammo depletion
                if (leftAmmo === 0 && !depletionEvents.some(e => e.includes('Left fleet out of ammo'))) {
                    depletionEvents.push(`Round ${round}: Left fleet out of ammo`);
                    log.push(`[CRITICAL] Left fleet out of ammo!`);
                }
            } else {
                rightAmmo -= rightAmmoRate;
                rightCooldownTimer = rightAttackCooldown;

                // Check for ammo depletion
                if (rightAmmo === 0 && !depletionEvents.some(e => e.includes('Right fleet out of ammo'))) {
                    depletionEvents.push(`Round ${round}: Right fleet out of ammo`);
                    log.push(`[CRITICAL] Right fleet out of ammo!`);
                }
            }

            // Check for alpha strike (on first ATTEMPT, not first hit)
            let alphaStrikeMultiplier = 1;
            if (isLeftAttacking && !leftAlphaStrikeUsed && leftFirstAttackAttempted && firstStriker === 'left') {
                alphaStrikeMultiplier = 1 + leftAlphaStrikeBonus / 100;
                leftAlphaStrikeUsed = true;
                if (leftAlphaStrikeBonus > 0) {
                    log.push(`Left ALPHA STRIKE! +${leftAlphaStrikeBonus}% damage`);
                }
            } else if (!isLeftAttacking && !rightAlphaStrikeUsed && rightFirstAttackAttempted && firstStriker === 'right') {
                alphaStrikeMultiplier = 1 + rightAlphaStrikeBonus / 100;
                rightAlphaStrikeUsed = true;
                if (rightAlphaStrikeBonus > 0) {
                    log.push(`Right ALPHA STRIKE! +${rightAlphaStrikeBonus}% damage`);
                }
            }

            // Calculate size-based hit chance
            let sizeHitChance = calculateSizeBasedHitChance(attackerSize, defenderSize);

            // Apply aim ability to reduce size penalty
            if (aimAbility > 0 && attackerSize > defenderSize) {
                let aimReduction = aimAbility / 100;
                sizeHitChance = sizeHitChance + (1 - sizeHitChance) * aimReduction * 0.5;
            }

            // Apply hit chance stat
            sizeHitChance *= hitChanceStat;

            // Check for first-strike stealth auto-dodge
            let defenderHasStealth = isLeftAttacking ?
                (!rightStealthBroken && rightStealth > 0) :
                (!leftStealthBroken && leftStealth > 0);
            let stealthRevealed = isLeftAttacking ? rightStealthRevealed : leftStealthRevealed;

            if (defenderHasStealth && !stealthRevealed) {
                log.push(`${attack.target} stealth field deflects initial ${attack.attacker} attack!`);
                if (isLeftAttacking) {
                    rightStealthRevealed = true;
                } else {
                    leftStealthRevealed = true;
                }
                continue; // Skip damage calculation
            }

            // Roll for hit/miss based on size
            if (!rollChance(sizeHitChance)) {
                log.push(`${attack.attacker} MISSED due to size difference! (${(sizeHitChance * 100).toFixed(0)}% hit chance)`);
                continue;
            }

            // Roll for dodge
            if (rollChance(defenderDodge)) {
                log.push(`${attack.attacker} attack DODGED!`);
                continue;
            }

            // Track successful hit
            if (isLeftAttacking) {
                leftHits++;
            } else {
                rightHits++;
            }

            // Calculate damage with RNG
            let attackDamage = 0;
            let blockedDamage = 0;

            for (let dmgType in damages) {
                if (damages[dmgType] > 0) {
                    // Check if this is bomb damage and consume missiles
                    if (dmgType === 'bomb') {
                        const attackerClass = isLeftAttacking ? leftClass : rightClass;
                        const attackerMissiles = isLeftAttacking ? leftMissiles : rightMissiles;
                        const attackerMissileConsumptionRate = isLeftAttacking ? leftMissileConsumptionRate : rightMissileConsumptionRate;

                        // Calculate missile consumption
                        const baseConsumption = classConsumptionRates[attackerClass]?.missile || 1;
                        const actualConsumption = Math.ceil(baseConsumption * attackerMissileConsumptionRate);

                        if (attackerMissiles <= 0) {
                            // No missiles available - skip bomb damage
                            log.push(`${attack.attacker} attempted bomb attack but has no missiles!`);
                            continue;
                        }

                        // Consume missiles
                        if (isLeftAttacking) {
                            leftMissiles = Math.max(0, leftMissiles - actualConsumption);
                            if (leftMissiles === 0 && !depletionEvents.some(e => e.includes('Left fleet out of missiles'))) {
                                depletionEvents.push(`Round ${round}: Left fleet out of missiles`);
                                log.push(`[CRITICAL] Left fleet out of missiles!`);
                            }
                        } else {
                            rightMissiles = Math.max(0, rightMissiles - actualConsumption);
                            if (rightMissiles === 0 && !depletionEvents.some(e => e.includes('Right fleet out of missiles'))) {
                                depletionEvents.push(`Round ${round}: Right fleet out of missiles`);
                                log.push(`[CRITICAL] Right fleet out of missiles!`);
                            }
                        }
                    }

                    // Apply damage range RNG
                    let baseDmg = damages[dmgType];
                    let minDmg = baseDmg * (1 - damageRange);
                    let maxDmg = baseDmg * (1 + damageRange);
                    let rolledDmg = randomRange(minDmg, maxDmg) * alphaStrikeMultiplier;

                    // Apply countermeasures (ship-based counter stats)
                    let counterValue = counters[dmgType] || 0;
                    let absorbed = Math.min(rolledDmg, counterValue);

                    // Counter resources ONLY work if ship has matching counter stat for this damage type
                    // Provides percentage-based damage reduction, scaled by ship class
                    let counterResourceBonus = 0;
                    if (counterValue > 0) {
                        // Ship has proper counter equipment for this damage type
                        const defenderClass = isLeftAttacking ? rightClass : leftClass;
                        const defenderCounters = isLeftAttacking ? rightCounterResource : leftCounterResource;
                        const defenderConsumptionRate = isLeftAttacking ? rightCounterConsumptionRate : leftCounterConsumptionRate;

                        if (defenderCounters > 0) {
                            // Counter resource provides +10% damage reduction per use
                            // Consumption rate: class-based (1 for XXS → 50 for TTN)
                            const baseConsumption = classConsumptionRates[defenderClass]?.counter || 1;
                            const actualConsumption = Math.ceil(baseConsumption * defenderConsumptionRate);

                            if (defenderCounters >= actualConsumption) {
                                // Calculate percentage-based bonus on remaining damage after counter stat
                                const remainingDmg = rolledDmg - absorbed;
                                counterResourceBonus = remainingDmg * 0.10; // 10% additional reduction

                                // Consume counter resources
                                if (!isLeftAttacking) {
                                    leftCounterResource -= actualConsumption;
                                    if (leftCounterResource === 0 && !depletionEvents.some(e => e.includes('Left fleet ran out of counters'))) {
                                        depletionEvents.push(`Round ${round}: Left fleet ran out of counters`);
                                        log.push(`[CRITICAL] Left fleet ran out of counters - reduced damage mitigation!`);
                                    }
                                } else {
                                    rightCounterResource -= actualConsumption;
                                    if (rightCounterResource === 0 && !depletionEvents.some(e => e.includes('Right fleet ran out of counters'))) {
                                        depletionEvents.push(`Round ${round}: Right fleet ran out of counters`);
                                        log.push(`[CRITICAL] Right fleet ran out of counters - reduced damage mitigation!`);
                                    }
                                }
                            }
                        }
                    }
                    // If counterValue === 0, counter resources are NOT consumed (wrong type)

                    // Total absorption = counter stat + counter resource bonus
                    let totalAbsorbed = absorbed + counterResourceBonus;
                    let effectiveDmg = rolledDmg - totalAbsorbed;

                    attackDamage += effectiveDmg;
                    blockedDamage += totalAbsorbed;

                    if (totalAbsorbed > 0) {
                        if (counterResourceBonus > 0) {
                            log.push(`  ${dmgType}: ${rolledDmg.toFixed(1)} - ${absorbed.toFixed(1)} (counter) - ${counterResourceBonus.toFixed(1)} (resource +10%) = ${effectiveDmg.toFixed(1)}`);
                        } else {
                            log.push(`  ${dmgType}: ${rolledDmg.toFixed(1)} - ${totalAbsorbed.toFixed(1)} absorbed = ${effectiveDmg.toFixed(1)}`);
                        }
                    }
                }
            }

            // Apply diversity bonus
            let diversityBonus = isLeftAttacking ? leftDiversityBonus : rightDiversityBonus;
            attackDamage *= diversityBonus;

            // Check for alpha shield on defender (first incoming attack)
            let alphaShieldReduction = 1;
            if (isLeftAttacking && !rightAlphaShieldUsed && round === 1) {
                alphaShieldReduction = 1 - rightAlphaShieldReduction;
                rightAlphaShieldUsed = true;
                if (rightAlphaShieldReduction > 0) {
                    log.push(`Right ALPHA SHIELD! -${(rightAlphaShieldReduction * 100).toFixed(0)}% damage`);
                }
            } else if (!isLeftAttacking && !leftAlphaShieldUsed && round === 1) {
                alphaShieldReduction = 1 - leftAlphaShieldReduction;
                leftAlphaShieldUsed = true;
                if (leftAlphaShieldReduction > 0) {
                    log.push(`Left ALPHA SHIELD! -${(leftAlphaShieldReduction * 100).toFixed(0)}% damage`);
                }
            }

            // Apply alpha shield reduction
            attackDamage *= alphaShieldReduction;

            // Apply damage
            let targetShields = isLeftAttacking ? rightCurrentShields : leftCurrentShields;
            let targetHP = isLeftAttacking ? rightCurrentHP : leftCurrentHP;

            let shieldDamage = Math.min(attackDamage, targetShields);
            let hullDamage = attackDamage - shieldDamage;

            if (isLeftAttacking) {
                rightCurrentShields -= shieldDamage;
                rightCurrentHP -= hullDamage;
                leftTotalDamageDealt += attackDamage;
            } else {
                leftCurrentShields -= shieldDamage;
                leftCurrentHP -= hullDamage;
                rightTotalDamageDealt += attackDamage;
            }

            log.push(`${attack.attacker} deals ${attackDamage.toFixed(1)} damage (${blockedDamage.toFixed(1)} blocked)`);
            if (shieldDamage > 0) log.push(`  Shield damage: ${shieldDamage.toFixed(1)}`);
            if (hullDamage > 0) log.push(`  Hull damage: ${hullDamage.toFixed(1)}`);
        }

        // Check for deaths after all attacks resolved (mutual destruction possible)
        if (leftCurrentHP <= 0 && rightCurrentHP <= 0) {
            log.push(`\nBoth fleets destroyed in mutual destruction!`);
            break;
        } else if (leftCurrentHP <= 0) {
            log.push(`\nLeft fleet destroyed!`);
            break;
        } else if (rightCurrentHP <= 0) {
            log.push(`\nRight fleet destroyed!`);
            break;
        }

        // Shield regeneration (check fuel availability)
        let leftShieldRegen = left.shield_recharge_rate || 0;
        let rightShieldRegen = right.shield_recharge_rate || 0;

        // Disable shield regen if out of fuel
        if (leftFuel <= 0) {
            if (leftShieldRegen > 0 && !depletionEvents.some(e => e.includes('Left fleet fuel depleted'))) {
                depletionEvents.push(`Round ${round}: Left fleet fuel depleted - shields stopped regenerating`);
                log.push(`[CRITICAL] Left fleet out of fuel - shields no longer regenerating!`);
            }
            leftShieldRegen = 0;
        }
        if (rightFuel <= 0) {
            if (rightShieldRegen > 0 && !depletionEvents.some(e => e.includes('Right fleet fuel depleted'))) {
                depletionEvents.push(`Round ${round}: Right fleet fuel depleted - shields stopped regenerating`);
                log.push(`[CRITICAL] Right fleet out of fuel - shields no longer regenerating!`);
            }
            rightShieldRegen = 0;
        }

        if (leftCurrentShields > 0 || round > (left.shield_break_delay || 0)) {
            leftCurrentShields = Math.min(leftShields, leftCurrentShields + leftShieldRegen);
            if (leftShieldRegen > 0) {
                log.push(`Left shields regenerate ${leftShieldRegen.toFixed(1)}`);
                // Consume fuel for shield regen
                if (leftFuel > 0) leftFuel -= 1;
            }
        }

        if (rightCurrentShields > 0 || round > (right.shield_break_delay || 0)) {
            rightCurrentShields = Math.min(rightShields, rightCurrentShields + rightShieldRegen);
            if (rightShieldRegen > 0) {
                log.push(`Right shields regenerate ${rightShieldRegen.toFixed(1)}`);
                // Consume fuel for shield regen
                if (rightFuel > 0) rightFuel -= 1;
            }
        }

        // Repair with toolkits (if damaged and toolkits available)
        if (leftCurrentHP < leftHP && leftToolkits > 0 && (left.repair_rate || 0) > 0) {
            let repairAmount = left.repair_rate || 0;
            leftCurrentHP = Math.min(leftHP, leftCurrentHP + repairAmount);
            leftToolkits--;
            log.push(`Left repairs ${repairAmount.toFixed(1)} HP (${leftToolkits} toolkits remaining)`);

            if (leftToolkits === 0 && !depletionEvents.some(e => e.includes('Left fleet ran out of toolkits'))) {
                depletionEvents.push(`Round ${round}: Left fleet ran out of toolkits`);
                log.push(`[CRITICAL] Left fleet out of toolkits - repairs disabled!`);
            }
        }

        if (rightCurrentHP < rightHP && rightToolkits > 0 && (right.repair_rate || 0) > 0) {
            let repairAmount = right.repair_rate || 0;
            rightCurrentHP = Math.min(rightHP, rightCurrentHP + repairAmount);
            rightToolkits--;
            log.push(`Right repairs ${repairAmount.toFixed(1)} HP (${rightToolkits} toolkits remaining)`);

            if (rightToolkits === 0 && !depletionEvents.some(e => e.includes('Right fleet ran out of toolkits'))) {
                depletionEvents.push(`Round ${round}: Right fleet ran out of toolkits`);
                log.push(`[CRITICAL] Right fleet out of toolkits - repairs disabled!`);
            }
        }

        // ENHANCED FOOD CONSUMPTION (class-based)
        let leftFoodUsed = Math.ceil(
            (classConsumptionRates[leftClass]?.food || 1) *
            (left.required_crew || 1) / 10 *
            leftFoodConsumptionRate
        );
        leftFood = Math.max(0, leftFood - leftFoodUsed);

        // Update food modifier dynamically
        leftFoodModifier = leftFood > 0 ? 0.5 + (0.5 * (leftFood / leftInitialFood)) : 0.5;

        let rightFoodUsed = Math.ceil(
            (classConsumptionRates[rightClass]?.food || 1) *
            (right.required_crew || 1) / 10 *
            rightFoodConsumptionRate
        );
        rightFood = Math.max(0, rightFood - rightFoodUsed);
        rightFoodModifier = rightFood > 0 ? 0.5 + (0.5 * (rightFood / rightInitialFood)) : 0.5;

        // ENHANCED FUEL CONSUMPTION (action-based)
        let leftFuelUsed = Math.ceil(
            (classConsumptionRates[leftClass]?.fuel || 5) *
            leftFuelConsumptionRate
        );

        // Additional fuel for actions this round
        let leftAttackedThisRound = attacks.some(a => a.attacker === 'left');
        if (leftAttackedThisRound) {
            leftFuelUsed += Math.ceil(leftFuelUsed * 0.3); // +30% for attacking
        }
        if (leftCurrentShields > leftShields * 0.5) { // Active shields
            leftFuelUsed += Math.ceil(leftFuelUsed * 0.2); // +20% for shields
        }

        leftFuel = Math.max(0, leftFuel - leftFuelUsed);

        // Update fuel modifier dynamically
        leftFuelModifier = leftFuel > 0 ? 0.5 + (0.5 * (leftFuel / leftInitialFuel)) : 0.5;

        let rightFuelUsed = Math.ceil(
            (classConsumptionRates[rightClass]?.fuel || 5) *
            rightFuelConsumptionRate
        );
        let rightAttackedThisRound = attacks.some(a => a.attacker === 'right');
        if (rightAttackedThisRound) {
            rightFuelUsed += Math.ceil(rightFuelUsed * 0.3);
        }
        if (rightCurrentShields > rightShields * 0.5) {
            rightFuelUsed += Math.ceil(rightFuelUsed * 0.2);
        }

        rightFuel = Math.max(0, rightFuel - rightFuelUsed);
        rightFuelModifier = rightFuel > 0 ? 0.5 + (0.5 * (rightFuel / rightInitialFuel)) : 0.5;

        if (leftFuel === 0 && depletionEvents.filter(e => e.includes('Left') && e.includes('fuel')).length === 0) {
            depletionEvents.push(`Round ${round}: Left fleet out of fuel`);
            log.push(`[CRITICAL] Left fleet out of fuel - dodge reduced!`);
        }
        if (rightFuel === 0 && depletionEvents.filter(e => e.includes('Right') && e.includes('fuel')).length === 0) {
            depletionEvents.push(`Round ${round}: Right fleet out of fuel`);
            log.push(`[CRITICAL] Right fleet out of fuel - dodge reduced!`);
        }

        log.push(`End of round: Left ${leftCurrentHP.toFixed(1)} HP / ${leftCurrentShields.toFixed(1)} shields, Right ${rightCurrentHP.toFixed(1)} HP / ${rightCurrentShields.toFixed(1)} shields`);

        // Check for stalemate (both alive but out of ammo)
        if (leftCurrentHP > 0 && rightCurrentHP > 0 &&
            leftAmmo < leftAmmoRate && rightAmmo < rightAmmoRate) {
            log.push(`\nSTALEMATE - Both fleets out of ammo!`);
            break;
        }
    }

    // Determine result
    let result;
    if (leftCurrentHP <= 0 && rightCurrentHP <= 0) {
        result = "MUTUAL DESTRUCTION";
    } else if (leftCurrentHP <= 0) {
        result = "RIGHT WINS";
    } else if (rightCurrentHP <= 0) {
        result = "LEFT WINS";
    } else if (leftAmmo < leftAmmoRate && rightAmmo < rightAmmoRate) {
        result = "STALEMATE";
    } else if (round >= config.maxRounds) {
        result = leftCurrentHP > rightCurrentHP ? "LEFT WINS (TIMEOUT)" :
            rightCurrentHP > leftCurrentHP ? "RIGHT WINS (TIMEOUT)" : "DRAW (TIMEOUT)";
    } else {
        result = "DRAW";
    }

    // Calculate accuracy
    let leftAccuracy = leftAttacks > 0 ? (leftHits / leftAttacks * 100) : 0;
    let rightAccuracy = rightAttacks > 0 ? (rightHits / rightAttacks * 100) : 0;

    // Summary
    log.push(`\n=== BATTLE SUMMARY ===`);
    log.push(`Result: ${result}`);
    log.push(`Total rounds: ${round}`);
    log.push(`Left: ${leftTotalDamageDealt.toFixed(1)} damage dealt, ${leftAttacks} attacks, ${leftHits} hits (${leftAccuracy.toFixed(0)}% accuracy)`);
    log.push(`Right: ${rightTotalDamageDealt.toFixed(1)} damage dealt, ${rightAttacks} attacks, ${rightHits} hits (${rightAccuracy.toFixed(0)}% accuracy)`);
    log.push(`Left ammo remaining: ${leftAmmo === Infinity ? 'Unlimited' : leftAmmo}`);
    log.push(`Right ammo remaining: ${rightAmmo === Infinity ? 'Unlimited' : rightAmmo}`);

    // Key factors
    let factors = [];
    if (leftAlphaStrikeUsed && leftAlphaStrikeBonus > 0) factors.push("Left alpha strike");
    if (rightAlphaStrikeUsed && rightAlphaStrikeBonus > 0) factors.push("Right alpha strike");
    if (leftAlphaShieldUsed && leftAlphaShieldReduction > 0) factors.push("Left alpha shield");
    if (rightAlphaShieldUsed && rightAlphaShieldReduction > 0) factors.push("Right alpha shield");
    if (leftAccuracy < 50) factors.push("Left poor accuracy");
    if (rightAccuracy < 50) factors.push("Right poor accuracy");
    let sizeRatio = leftShipSize / rightShipSize;
    if (sizeRatio > 1.5) factors.push("Left struggled to hit smaller target");
    if (sizeRatio < 0.67) factors.push("Right struggled to hit smaller target");
    if (leftBaseDodge > 0.5) factors.push("Left high evasion");
    if (rightBaseDodge > 0.5) factors.push("Right high evasion");
    if (result === "STALEMATE") factors.push("Ammo depletion");
    if (result === "MUTUAL DESTRUCTION") factors.push("Simultaneous destruction");

    // Add consumable factors
    if (leftConsumables && leftConsumables.stimulants && leftConsumables.stimulants.length > 0) {
        factors.push(`Left fleet used ${leftConsumables.stimulants.length} stimulants: ${leftConsumables.stimulants.map(s => s.name).join(', ')}`);
    }
    if (rightConsumables && rightConsumables.stimulants && rightConsumables.stimulants.length > 0) {
        factors.push(`Right fleet used ${rightConsumables.stimulants.length} stimulants: ${rightConsumables.stimulants.map(s => s.name).join(', ')}`);
    }

    // Add consumable depletion to key factors
    if (leftAmmo === 0) factors.push(`Left fleet ran out of ammo`);
